-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.furnace_target(p_world uuid, c creature, p_kind text, p_output boolean, p_x double precision, p_y double precision)
 RETURNS placed
 LANGUAGE sql
 STABLE
AS $function$
  select p.* from placed p, my_deed(p_world, c.keeper) dd
   where dd.world_id is not null and p.world_id = p_world and p.kind = case when p_kind = 'smelt' then 'smelter' else 'kiln' end
     and p.x between dd.x - work_range(c) and dd.x + work_range(c) and p.y between dd.y - work_range(c) and dd.y + work_range(c)
     and greatest(abs(p.x - dd.x), abs(p.y - dd.y)) <= work_range(c) and on_home_deed(p_world, c.keeper, p.x, p.y)
     and case when p_output then jsonb_array_length(furnace_output(p)) > 0
              else jsonb_array_length(furnace_jobs(p)) < furnace_capacity(p) end
   order by (p.cx - p_x) ^ 2 + (p.cy - p_y) ^ 2, p.id limit 1
$function$
